// Find Lead Phone: one Hub Contacts row, answered synchronously. POST /webhook/waterfall-phones with
// { recordId, signature_phone?, force?, clientRecordId? }: Enrich Qualify new lead from PlusVibe,
// Email Bison and Alta all call it this way and put the number on their Slack cards. The path keeps
// its old name so the handlers are untouched.
// signature_phone exists only here: only a caller holding the RAW reply has it. Everything else is
// read off the Hub row itself. A helper writes no Hub Automations row: the handler's row carries the
// phone and where it came from.
const s = (v) => String(v == null ? '' : v).trim();
let b = null;
try { const w = $('Contact Door').first().json; if (w) b = w.body || w; } catch (e) { b = null; }
if (!b) b = {};
const recordId = s(b.recordId);
return [{ json: {
  startedAt: new Date().toISOString(),
  recordId,
  force: b.force === true || s(b.force) === 'true',
  clientRecordId: s(b.clientRecordId),
  signature_phone: s(b.signature_phone),
  _invalid: !recordId,
  _error: recordId ? '' : 'payload needs recordId',
} }];

// Builds the person and the phone accumulator from the Hub Contacts row.
const p0 = $('Contact Params').first().json;
const s = (v) => { if (Array.isArray(v)) v = v[0]; return String(v == null ? '' : v).trim(); };
let f = null;
try { const r = $('Fetch Row').first().json || {}; f = r.fields || (r.id ? r : null); } catch (e) { f = null; }
const acc = { phone: '', source: 'none', tf: '', tf_source: '', tried: [], skipped: [], failed: [] };
const out = { recordId: p0.recordId, force: p0.force, clientRecordId: p0.clientRecordId, person: {}, companyId: '', acc, _invalid: p0._invalid, _error: p0._error };
if (out._invalid) return [{ json: out }];
if (!f) { out._invalid = true; out._error = 'contact ' + p0.recordId + ' not readable'; return [{ json: out }]; }
const FREEMAIL = new Set(['gmail.com','yahoo.com','outlook.com','hotmail.com','icloud.com','aol.com','proton.me','protonmail.com','live.com','msn.com','gmx.com','mail.com','walla.co.il','walla.com']);
const email = s(f.email).toLowerCase();
let domain = s(f.domain).toLowerCase();
if (!domain && email.includes('@')) { const d = email.split('@')[1]; if (d && !FREEMAIL.has(d)) domain = d; }
out.person = {
  email,
  first_name: s(f.firstName),
  last_name: s(f.lastName),
  full_name: (s(f.firstName) + ' ' + s(f.lastName)).trim(),
  domain,
  linkedin: s(f.linkedin),
};
// The contact links to its company Prospect row, which carries the synced
// Conversation Thread. The scrape step reads it for a signature phone.
const link = f.Company;
if (Array.isArray(link) && link.length) out.companyId = String(link[0] && link[0].id ? link[0].id : link[0]);
else if (link && Array.isArray(link.linkedRecordIds) && link.linkedRecordIds.length) out.companyId = String(link.linkedRecordIds[0]);
const isTollFree = (p) => { let x = String(p || '').replace(/\D/g, ''); if (x.length === 11 && x.charAt(0) === '1') x = x.slice(1); return x.length === 10 && /^(?:800|833|844|855|866|877|888)/.test(x); };
const existingPhone = s(f.phone);
if (existingPhone && !p0.force) { acc.phone = existingPhone; acc.source = 'existing'; return [{ json: out }]; }
const sig = p0.signature_phone;
if (sig) {
  acc.tried.push('signature');
  if (isTollFree(sig)) { acc.tf = sig; acc.tf_source = 'signature-tollfree'; }
  else { acc.phone = sig; acc.source = 'signature'; }
}
return [{ json: out }];

// Tier 0b: the stored Conversation Thread on the company Prospect row.
// The 12-hourly thread syncs keep signature blocks intact (proven live 2026-08-20:
// Zeron, MX Wholesale, What A Move all carry the lead's number in THEM messages),
// so a Hub contact fired by record id alone can still get the signature phone.
// A signature_phone passed in the payload (Handle New Lead, raw reply in hand) wins.
const prev = $('Person').first().json;
const j = Object.assign({}, prev);
const acc = j.acc;
if (acc.phone) return [{ json: j }];
let thread = '';
try { const r = $('Fetch Company').first().json || {}; const f = r.fields || {}; thread = String(f['Conversation Thread'] || f['Conversation Thread OLD'] || ''); } catch (e) { thread = ''; }
if (!thread) return [{ json: j }];
if (acc.tried.indexOf('signature') === -1) acc.tried.push('signature');
// Collect THEM blocks only: the lead's own messages, where their signature lives.
const blocks = [];
const re = /\*\*\[[^\]]*\]\s*(THEM|US):\*\*/g;
let m, marks = [];
while ((m = re.exec(thread)) !== null) marks.push({ dir: m[1], start: m.index, end: re.lastIndex });
for (let i = 0; i < marks.length; i++) {
  if (marks[i].dir !== 'THEM') continue;
  const bodyEnd = i + 1 < marks.length ? marks[i + 1].start : thread.length;
  blocks.push(thread.slice(marks[i].end, bodyEnd));
}
if (!blocks.length) blocks.push(thread);
// URLs, cid: refs, and bracketed asset tags carry long digit runs (upload timestamps,
// uuids) that pattern-match as phones — proven by a live false positive (a Dropbox
// filename's 20240212154056). Strip them, then accept only formatted numbers: a bare
// unbroken 11+ digit run without a leading + is never a real signature phone.
const scrub = (txt) => String(txt || '')
  .replace(/https?:\/\/\S+/gi, ' ')
  .replace(/\bwww\.\S+/gi, ' ')
  .replace(/\bcid:\S+/gi, ' ')
  .replace(/\[[^\]\n]*\]/g, ' ');
const grabPhones = (txt) => { const out = []; const pre = /(?:\+?\d{1,3}[\t .\-]?)?(?:\(?\d{2,4}\)?[\t .\-]?){2,4}\d{2,4}/g; let mm; while ((mm = pre.exec(scrub(txt))) !== null) { const raw = mm[0].trim(); const dg = raw.replace(/\D/g, ''); if (dg.length < 9 || dg.length > 15) continue; if (/^\d{11,}$/.test(raw)) continue; out.push({ raw, dg }); } return out; };
const isTollFree = (dg) => { let x = String(dg || ''); if (x.length === 11 && x.charAt(0) === '1') x = x.slice(1); return x.length === 10 && /^(?:800|833|844|855|866|877|888)/.test(x); };
// Latest reply first: the freshest signature is the most likely direct line.
let hit = '', tf = '';
for (let i = blocks.length - 1; i >= 0 && !hit; i--) {
  for (const c of grabPhones(blocks[i])) {
    if (isTollFree(c.dg)) { if (!tf) tf = c.raw; }
    else { hit = c.raw; break; }
  }
}
if (hit) { acc.phone = hit; acc.source = 'signature'; }
else if (tf && !acc.tf) { acc.tf = tf; acc.tf_source = 'signature-tollfree'; }
return [{ json: j }];

// FE Prep: decides whether FullEnrich is asked for this lead, and builds the one-contact submission.
// A direct number already in hand (the row's own phone, or the reply signature) ends the search for
// free. A toll-free signature does not: FullEnrich is still asked for a direct line, and the
// switchboard stays the fallback. Asked by LinkedIn URL when the row holds one, else by first name +
// last name + domain; a lead with neither cannot be asked and the skip is named in the answer.
const j = Object.assign({}, $input.first().json || {});
const acc = j.acc || { phone: '', source: 'none', tf: '', tf_source: '', tried: [], skipped: [], failed: [] };
j.acc = acc;
j._call = false;
if (j._invalid || acc.phone) return [{ json: j }];
const p = j.person || {};
const cut = (v) => String(v || '').slice(0, 100);
if (!(p.linkedin || (p.first_name && p.last_name && p.domain))) {
  acc.skipped.push('FullEnrich: cannot be asked (no LinkedIn URL and no first name + last name + domain)');
  return [{ json: j }];
}
const c = { enrich_fields: ['contact.phones'], custom: { row_id: String(j.recordId) } };
if (p.first_name && p.last_name) { c.first_name = cut(p.first_name); c.last_name = cut(p.last_name); }
if (p.domain) c.domain = cut(p.domain);
if (p.linkedin) c.linkedin_url = p.linkedin;
j._call = true;
j.body = { name: 'Find Lead Phone ' + String(j.recordId), data: [c] };
acc.tried.push('FullEnrich');
return [{ json: j }];

// Submit Check: FullEnrich's answer to the submission becomes the poll carrier: the enrichment id, or
// the reason there is none. No credential on the node, a refused key, no credits, a rate limit or a
// dead API are all a named skip on the batch, never a crash: the people it carried stay retryable.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object
// with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const j=$input.first().json||{};
const carrier={ enrichmentId:'', submitErr:'', status:'', polls:0, _force:false, _loop:false, _t0:Date.now() };
if(j.error&&j.body===undefined&&j.enrichment_id===undefined){
  const m=errMsg(j.error);
  carrier.submitErr=(/credential/i.test(m)?'FullEnrich: no credential on the FullEnrich nodes':'FullEnrich: '+m).slice(0,200);
  return [{ json:carrier }];
}
const code=Number(j.statusCode)||200;
let b=(j.body!==undefined)?j.body:j;
if(typeof b==='string'){ try{ b=JSON.parse(b); }catch(e){ b={ message:b }; } }
b=b||{};
if(code>=200&&code<300&&b.enrichment_id){ carrier.enrichmentId=String(b.enrichment_id); carrier.status='CREATED'; return [{ json:carrier }]; }
const why=String(b.code||'')+' '+String(b.message||'');
if(code===401||/authorization|api\.key/i.test(why)) carrier.submitErr='FullEnrich: the API key was refused (HTTP '+code+' '+why.trim()+')';
else if(code===402||/credit/i.test(why)) carrier.submitErr='FullEnrich: out of credits (HTTP '+code+' '+why.trim()+')';
else if(code===429) carrier.submitErr='FullEnrich: rate limited at submit (HTTP 429 '+why.trim()+')';
else carrier.submitErr=('FullEnrich: submit refused (HTTP '+code+' '+(why.trim()||JSON.stringify(b).slice(0,120))+')');
carrier.submitErr=carrier.submitErr.slice(0,200);
return [{ json:carrier }];

// Poll Input: the carrier of the open enrichment, re-emitted each round so FE Poll asks once and
// Poll Gate folds the answer onto it. First round from Submit Check, later rounds from the Wait.
const c=Object.assign({}, $input.first().json||{});
delete c.found;
return [{ json:c }];

// Poll Gate: one status answer folded onto the carrier. FullEnrich says CREATED or IN_PROGRESS while
// it works (or answers 400 error.enrichment.in_progress), and FINISHED, CANCELED or
// CREDITS_INSUFFICIENT when it has stopped. The loop asks every 10 seconds for up to 90 seconds (the calling handler waits 120); at
// the cap one last read is forced (forceResults) so whatever FullEnrich found so far is kept, and the
// people without an answer stay retryable. Only the phones ride on: the profile FullEnrich sends back
// with a LinkedIn lookup is dropped here so the batch stays small.
const MAX=90*1000, WAIT=10;
const c=Object.assign({}, $('Poll Input').first().json||{});
const j=$input.first().json||{};
const code=Number(j.statusCode)||0;
let b=(j.body!==undefined)?j.body:j;
if(typeof b==='string'){ try{ b=JSON.parse(b); }catch(e){ b={}; } }
b=b||{};
const elapsed=Date.now()-(Number(c._t0)||Date.now());
c.polls=(Number(c.polls)||0)+1;
const wasForced=!!c._force;
const pick=(list)=>(Array.isArray(list)?list:[]).map(d=>{
  const ci=(d&&d.contact_info)||{};
  const ph=ci.most_probable_phone||((Array.isArray(ci.phones)&&ci.phones[0])||null);
  return { rowId:String(((d&&d.custom)||{}).row_id||''), number:ph?String(ph.number||''):'', lineType:ph?String(ph.line_type||''):'', region:ph?String(ph.region||''):'' };
}).filter(x=>x.rowId);
const STOPPED=['FINISHED','CANCELED','CREDITS_INSUFFICIENT'];
let settled=false;
if(j.error&&j.body===undefined&&b.status===undefined){
  c.pollErr=String((j.error&&j.error.message)||j.error||'poll failed').slice(0,160);
} else if(code===401||code===404){
  c.pollErr='HTTP '+code+' '+String(b.code||'')+' '+String(b.message||''); c.status='UNREADABLE'; settled=true;
} else if(b.status){
  c.status=String(b.status); c.pollErr='';
  if(STOPPED.indexOf(c.status)>-1||wasForced){ c.found=pick(b.data); c.credits=Number((b.cost||{}).credits)||0; settled=true; }
} else {
  // 400 error.enrichment.in_progress, 429, or an answer without a status: still open.
  c.pollErr=(code&&code!==400)?('HTTP '+code+' '+String(b.code||'')):'';
}
if(!settled&&wasForced){ settled=true; }
if(!settled&&elapsed>=MAX){ c._force=true; }
c.timedOut=settled&&wasForced&&STOPPED.indexOf(c.status)<0;
c._loop=!settled;
c._nextWaitSec=c._force?1:WAIT;
c._elapsedS=Math.round(elapsed/1000);
return [{ json:c }];

// FE Parse: FullEnrich's answer folded onto the lead. The carrier arrives on the input: from the poll
// loop when it settled (or hit the 90-second cap, where one forced read keeps whatever was found),
// from Submit Check when the submission was refused. A number found is the lead's phone; no
// credential or no credits is a named skip; anything else that kept FullEnrich from answering is a
// named failure. The lead flows on either way.
const j = Object.assign({}, $('FE Prep').first().json || {});
delete j.body;
const acc = j.acc;
const c = $input.first().json || {};
const x = (c.found || [])[0] || null;
if (x && x.number) {
  acc.phone = x.number;
  acc.source = 'FullEnrich';
  acc.line_type = String(x.lineType || '').toLowerCase() || 'unknown';
} else if (c.submitErr) {
  if (/no credential|out of credits/.test(c.submitErr)) acc.skipped.push(c.submitErr); else acc.failed.push(c.submitErr);
} else if (c.status === 'CREDITS_INSUFFICIENT') {
  acc.skipped.push('FullEnrich: out of credits');
} else if (c.status === 'UNREADABLE' || c.status === 'CANCELED') {
  acc.failed.push('FullEnrich: enrichment ' + (c.enrichmentId || '?') + ' ' + c.status.toLowerCase() + ' ' + (c.pollErr || ''));
} else if (c.timedOut) {
  acc.failed.push('FullEnrich: no answer inside 90 seconds (enrichment ' + (c.enrichmentId || '?') + ' may still finish and charge on their side)');
}
return [{ json: j }];

// The verdict. A direct number wins (the row's own phone, the reply signature, FullEnrich); a
// toll-free signature is the last resort and says so in its source. The response body is what the
// calling handler gets back synchronously and puts on its Slack card and in its own run row.
const j0 = $input.first().json;
const j = Object.assign({}, j0); delete j.body;
const toE164 = (raw) => {
  const t = String(raw || '').trim();
  if (!t) return '';
  const d = t.replace(/\D/g, '');
  if (t.charAt(0) === '+') return '+' + d;
  if (d.length === 11 && d.charAt(0) === '1') return '+' + d;
  if (d.length === 10 && d.charAt(0) !== '0') return '+1' + d;
  return t;
};
if (j._invalid) {
  j.result = { ok: false, error: j._error || 'invalid payload', phone: '', phone_source: 'none' };
  j._writeback = false;
  return [{ json: j }];
}
const acc = j.acc;
let phone = acc.phone, source = acc.source;
if (!phone && acc.tf) { phone = acc.tf; source = acc.tf_source; }
if (!phone) source = 'none';
phone = toE164(phone);
j.result = { ok: true, phone, phone_source: source, line_type: acc.line_type || '', tried: acc.tried, skipped: acc.skipped, failed: acc.failed, recordId: j.recordId || '' };
j._writeback = !!phone && source !== 'existing';
return [{ json: j }];

// The single update item for the Hub Contacts row.
const f = $('Finalize').first().json;
return [{ json: { id: f.recordId, phone: f.result.phone, 'Phone Source': f.result.phone_source } }];
